import SwiftUI
import Observation
struct Parcel {
    let id, status: String
    func findStatus(for number: String) -> String? {
        number == id ? status : nil
    }
}
@Observable final class TrackingViewModel {
    var number = ""
    var message = "Введите номер"
    var includeNumber = false
    private var searchedNumber = ""
    var displayMessage: String {
        guard includeNumber && !searchedNumber.isEmpty else { return message }
        return "\(searchedNumber): \(message)"
    }
    private let parcel = Parcel(id: "PK42", status: "В пути")
    func search() {
        searchedNumber = number
        let status = parcel.findStatus(for: number) ?? "Не найдено"
        message = number.isEmpty ? "Введите номер" : status
    }
}
struct TrackingScreen: View {
    @State private var viewModel = TrackingViewModel()
    var body: some View {
        VStack {
            TextField("Номер", text: $viewModel.number)
            Button("Проверить") { viewModel.search() }
            Toggle("Показать номер", isOn: $viewModel.includeNumber)
            Text(viewModel.displayMessage)
        }
    }
}

ViewModel хранит searchedNumber вместе с результатом и флаг оформления. displayMessage вычисляется из сохранённого номера и message, поэтому новый черновик не подписывает старый ответ чужим id.

import SwiftUI
import Observation
struct Parcel {
    let id: String
    let weightKg: Int
    func totalWeight(copies: Int) -> Int { weightKg * copies }
}
@Observable final class WeightViewModel {
    var copies = 1
    private let parcel = Parcel(id: "PK42", weightKg: 2)
    var weightText: String { "Вес: \(parcel.totalWeight(copies: copies)) кг" }
}
struct WeightScreen: View {
    @State private var viewModel = WeightViewModel()
    var body: some View {
        VStack {
            Stepper("Коробок: \(viewModel.copies)",
                    value: $viewModel.copies, in: 1...3)
            Text(viewModel.weightText)
        }
    }
}

Model считает вес, ViewModel превращает его в строку, View редактирует количество и показывает результат. Диапазон ограничивает управление Stepper; проверка расчёта возможна без интерфейса.
